#!/usr/bin/env bash
# Some portions generated by Codex. Separate JFR diagnostics; not clean timing evidence.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_B:?}" "${CP_C:?}" "${CP_D:?}" "${LOCK:?}"
: "${BASELINE_SHA:?Published baseline identity required}" "${COMBINED_SHA:?Published combined identity required}"
: "${SOURCE_PULL_SHA:?}" "${WRITER_GUARD_SHA:?}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
JFR=${JFR:-../toolchain/jdk-25.0.5+8/bin/jfr}
OUT=${OUT:-experiments/threadlocal-audit/source-pull/four-arm-profiles-01}
if [[ -e "$OUT" ]]; then echo "Refusing existing output directory: $OUT" >&2; exit 2; fi
mkdir -p "$OUT/harness"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_D" -d "$OUT/harness" experiments/threadlocal-audit/ThreadLocalQueryBenchmark.java
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640)
{
 date -u; "$JAVA" -version; echo A_PUBLISHED="$BASELINE_SHA"; echo D_PUBLISHED="$COMBINED_SHA"; echo SOURCE_PULL_SHA="$SOURCE_PULL_SHA"; echo WRITER_GUARD_SHA="$WRITER_GUARD_SHA"
 printf 'CP_A=%s\nCP_B=%s\nCP_C=%s\nCP_D=%s\n' "$CP_A" "$CP_B" "$CP_C" "$CP_D"
 printf '%s\n' "${FLAGS[@]}"
 sha256sum experiments/threadlocal-audit/ThreadLocalQueryBenchmark.java
} > "$OUT/environment.txt" 2>&1
printf '%s\n' 'Diagnostic-only JFR profile settings; fresh JVM per arm/route;20 warmups excluded; regular5 recorded/native30 recorded;100k six-slot results. Each recording starts immediately before first measured query, after warmup. Same immutable arm classpaths as clean factorial timing. Inclusive method samples overlap; no exact lookup-count or wall-time attribution.' > "$OUT/PROTOCOL.txt"
for regime in regular interpreted janino; do
 # One profile per arm; use Latin-square row1, not a claim of statistical balance with one sample.
 for arm in A B D C; do
  var="CP_$arm"; cp=${!var}; file="$(realpath "$OUT")/$regime-$arm"
  iterations=30; [[ $regime == regular ]] && iterations=5
  "$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}" "-Daudit.regime=$regime" \
   -Doverlay.benchmark.warmups=20 -Daudit.shape=narrow "-Daudit.jfr=$file.jfr" -cp "$OUT/harness:$cp" \
   org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalQueryBenchmark 100 10 "$iterations" true > "$file.log" 2>&1
  "$JFR" print --json --events jdk.ExecutionSample,jdk.NativeMethodSample "$file.jfr" > "$file.samples.json"
 done
done
python3 experiments/threadlocal-audit/summarize-profiles.py "$OUT" > "$OUT/summary.json"
python3 - "$OUT" <<'PY'
import pathlib,sys
root=pathlib.Path(sys.argv[1]); seen=set()
for p in root.glob('*.log'):
 for line in p.read_text().splitlines():
  if line.startswith('audit '):
   d=dict(t.split('=',1) for t in line.split()[1:]);seen.add(tuple(d[k] for k in ('rows','checksum','checksum2')))
expected=('100000','1899306305404719472','3694550068168048289')
if seen!={expected}:raise ValueError(f'Profile checksum mismatch: {seen}')
if len(list(root.glob('*.jfr')))!=12:raise ValueError('Missing profile arms')
print('All12 profile arms completed with expected dual checksums.')
PY
